 function reportRows(){return students.map(s=>{const a=attendance.filter(x=>x.student_id===s.id),c=k=>a.filter(k).length;const row={'الرقم':s.student_number,'الاسم':s.full_name,'حاضر':c(x=>x.status==='present'),'تأخر':c(x=>x.status==='late'),'غياب عادي':c(x=>x.status==='absent'&&(!x.absence_reason||x.absence_reason==='ordinary')),'رخصة':c(x=>x.absence_reason==='permission'),'إعفاء':c(x=>x.absence_reason==='exempt'),'واجب رسمي':c(x=>x.absence_reason==='official_duty')};tests.forEach(t=>{const r=results.find(x=>x.student_id===s.id&&x.test_id===t.id);row[t.name+(t.unit?' ('+t.unit+')':'')]=r?r.raw_value:''});const w=meas.find(x=>x.student_id===s.id&&x.weight_kg!=null);row['آخر وزن (كغ)']=w?w.weight_kg:'';return row})}
