 async function addTest(){if(!testForm.name.trim())return notify('اكتب اسم الاختبار');await insert('test_definitions',{institution_id:profile.institution_id,...testForm,name:testForm.name.trim()},'تمت إضافة الاختبار');setTestForm({name:'',unit:'',higher_is_better:true})}
 async function saveScale(){if(!scaleTest||!scale.trim())return notify('اختر الاختبار وأدخل جدول التنقيط');let rules;try{rules=JSON.parse(scale);if(!Array.isArray(rules))throw new Error('JSON must be array')}catch{rules=scale.trim().split(/\r?\n/).map(line=>line.trim()).filter(Boolean).map(line=>line.split(/[\t,;|]+/).map(x=>x.trim())).filter(cols=>cols.length>=2&&Number.isFinite(Number(cols[0]))&&Number.isFinite(Number(cols[1]))).map(cols=>({rawValue:Number(cols[0]),score:Number(cols[1])}));if(!rules.length)return notify('تعذّر قراءة الجدول. الصق عمود النتيجة الخام ثم الدرجة، مفصولين بعلامة Tab أو فاصلة.')}if(rules.some(x=>!Number.isFinite(Number(x.rawValue))||!Number.isFinite(Number(x.score))))return notify('توجد قيم غير رقمية في BARÈME');const{data:vers,error:ve}=await supabase.from('scale_versions').select('version').eq('test_id',scaleTest).order('version',{ascending:false}).limit(1);if(ve)return notify(msg(ve));const version=(vers?.[0]?.version||0)+1;await insert('scale_versions',{institution_id:profile.institution_id,test_id:scaleTest,version,valid_from:today(),rules},`تم حفظ إصدار BARÈME رقم ${version}`);}
 async function saveResult(){if(viewingArchived)return notify('هذه سنة مؤرشفة (قراءة فقط)');if(!resultForm.student_id||!resultForm.test_id||resultForm.raw_value==='')return notify('أكمل بيانات النتيجة');const raw=Number(resultForm.raw_value);if(!Number.isFinite(raw))return notify('النتيجة يجب أن تكون رقمًا');const{data:sv,error}=await supabase.from('scale_versions').select('*').eq('test_id',resultForm.test_id).lte('valid_from',resultForm.tested_on).order('version',{ascending:false}).limit(1);if(error)return notify(msg(error));let score=null,scale_version_id=null;if(sv?.length){scale_version_id=sv[0].id;const rules=Array.isArray(sv[0].rules)?sv[0].rules:[];const matches=rules.filter(x=>Number.isFinite(Number(x.rawValue))&&Number(x.rawValue)>=raw);if(matches.length){matches.sort((a,b)=>Number(a.rawValue)-Number(b.rawValue));score=Number(matches[0].score)}}const{error:er}=await supabase.from('test_results').insert({institution_id:profile.institution_id,student_id:resultForm.student_id,test_id:resultForm.test_id,raw_value:raw,score,scale_version_id,tested_on:resultForm.tested_on,recorded_by:profile.id});if(er)notify(msg(er));else{notify(score===null?'حُفظت النتيجة الخام؛ لا يوجد تطابق في BARÈME.':'تم حفظ النتيجة والدرجة');setResultForm({...resultForm,raw_value:''});loadAll()}}
 async function startSession(){if(navigator.onLine)await supabase.from('sessions').update({end_time:'23:59:00'}).eq('coach_id',profile.id).is('end_time',null);await insert('sessions',{institution_id:profile.institution_id,coach_id:profile.id,session_date:today(),start_time:new Date().toTimeString().slice(0,8)},'بدأت الحصة')}
 async function endSession(s){const{error}=await supabase.from('sessions').update({end_time:new Date().toTimeString().slice(0,8)}).eq('id',s.id).eq('coach_id',profile.id);if(error)notify(msg(error));else{notify('تم إنهاء الحصة');loadAll()}}
 async function updateMember(member,patch){const{error}=await supabase.from('profiles').update(patch).eq('id',member.id);if(error)notify(msg(error));else{notify('تم تحديث الحساب');loadAll()}}
 async function handleRehab(n){const{error}=await supabase.from('rehab_notifications').update({status:'handled',handled_by:profile.id,handled_at:new Date().toISOString()}).eq('id',n.id);if(error)notify(msg(error));else{notify('تمت معالجة التنبيه');loadAll()}}
 async function saveInstitution(){if(!admin)return;let logo_url=inst?.logo_url||null;if(logoFile){const path=`institution/${Date.now()}-${logoFile.name.replace(/[^a-zA-Z0-9._-]/g,'_')}`;const{error:up}=await supabase.storage.from('institution-assets').upload(path,logoFile,{upsert:true});if(up)return notify('رفع الشعار فشل: '+msg(up));const{data}=supabase.storage.from('institution-assets').getPublicUrl(path);logo_url=data.publicUrl}const{error}=await supabase.from('institutions').update({name:instName.trim(),logo_url}).eq('id',profile.institution_id);if(error)notify(msg(error));else{notify('تم حفظ إعدادات المؤسسة');loadAll()}}
 const filtered=useMemo(()=>students.filter(s=>(s.full_name||'').includes(search)||String(s.student_number||'').includes(search)),[students,search])
