 if(!profile||profile.status!=='active')return <div className="auth-screen"><div className="auth-card"><div className="auth-mark"><Lock/></div><h2>{profile?.status==='suspended'?'الحساب موقوف':'الحساب بانتظار الموافقة'}</h2><p>{profile?.status==='suspended'?'يرجى التواصل مع إدارة المؤسسة.':'سيتم تفعيل حسابك من طرف إدارة المؤسسة بعد مراجعته.'}</p><button className="btn btn-primary block" onClick={loadProfile}>تحديث الحالة</button><button className="link-button" onClick={signout}>تسجيل الخروج</button></div></div>
